def _deskew_and_find_h_lines(pil_img: Image.Image) -> tuple[list[int], Image.Image]:
    """Deskew scanned page image (-1.5° to +1.5°) and locate horizontal table grid lines."""
    w0, h0 = pil_img.size
    small = pil_img.convert("L").resize((max(1, w0 // 2), max(1, h0 // 2)), Image.BILINEAR)
    best_angle = 0.0
    best_score = -1.0
    for angle in np.linspace(-1.5, 1.5, 31):
        rot = small.rotate(float(angle), resample=Image.BILINEAR, fillcolor=255)
        arr = (np.array(rot) < 175).astype(np.float32)
        ih, iw = arr.shape
        inner = arr[int(ih * 0.05) : int(ih * 0.95), int(iw * 0.08) : int(iw * 0.92)]
        row_means = inner.mean(axis=1)
        score = float(np.sum(row_means**4))
        if score > best_score:
            best_score = score
            best_angle = float(angle)

    if abs(best_angle) > 0.01:
        pil_img = pil_img.rotate(best_angle, resample=Image.BICUBIC, fillcolor=255)

    gray = np.array(pil_img.convert("L"))
    h, w = gray.shape
    dark = (gray < 180).astype(np.uint8)
    margin_y, margin_x = int(h * 0.03), int(w * 0.03)
    dark[:margin_y, :] = 0
    dark[h - margin_y :, :] = 0
    dark[:, :margin_x] = 0
    dark[:, w - margin_x :] = 0

    dark_v3 = np.maximum(dark, np.maximum(np.roll(dark, 1, axis=0), np.roll(dark, -1, axis=0)))
    row_proj = dark_v3[:, int(w * 0.1) : int(w * 0.9)].mean(axis=1)
    h_candidates = np.where(row_proj > 0.50)[0]

    raw_h_lines: list[int] = []
    if len(h_candidates) > 0:
        cluster = [int(h_candidates[0])]
        for y in h_candidates[1:]:
            if int(y) - cluster[-1] <= 10:
                cluster.append(int(y))
            else:
                raw_h_lines.append(int(np.mean(cluster)))
                cluster = [int(y)]
        raw_h_lines.append(int(np.mean(cluster)))

    best_group: list[int] = []
    if raw_h_lines:
        curr_group = [raw_h_lines[0]]
        for y in raw_h_lines[1:]:
            if 18 <= (y - curr_group[-1]) <= 140:
                curr_group.append(y)
            else:
                if len(curr_group) > len(best_group):
                    best_group = curr_group
                curr_group = [y]
        if len(curr_group) > len(best_group):
            best_group = curr_group

    return best_group, pil_img


def _find_true_v_lines(pil_img: Image.Image, h_lines: list[int]) -> tuple[list[int], np.ndarray]:
    """Locate continuous vertical grid lines across the detected table vertical span."""
    gray = np.array(pil_img.convert("L"))
    if len(h_lines) < 2:
        return [], gray
    dark = (gray < 180).astype(np.uint8)
    y_top, y_bot = h_lines[0], h_lines[-1]
    dark_h3 = np.maximum(dark, np.maximum(np.roll(dark, 1, axis=1), np.roll(dark, -1, axis=1)))
    col_proj = dark_h3[y_top : y_bot + 1, :].mean(axis=0)
    v_candidates = np.where(col_proj > 0.78)[0]

    v_lines: list[int] = []
    if len(v_candidates) > 0:
        cluster = [int(v_candidates[0])]
        for x in v_candidates[1:]:
            if int(x) - cluster[-1] <= 18:
                cluster.append(int(x))
            else:
                v_lines.append(int(np.mean(cluster)))
                cluster = [int(x)]
        v_lines.append(int(np.mean(cluster)))
    return v_lines, gray


def _segment_cell_chars(cell_gray: np.ndarray) -> list[tuple[int, int, int, int]]:
    """Segment a cropped grayscale table cell into character bounding boxes (sx, sy, ex, ey)."""
    h, w = cell_gray.shape
    if h < 6 or w < 6:
        return []
    thresh = min(190, int(np.percentile(cell_gray, 15) + 50))
    bw = (cell_gray < thresh).astype(np.uint8)
    row_ink = bw.sum(axis=1)
    active_y = np.where(row_ink >= 2)[0]
    if len(active_y) == 0:
        return []

    y_center = int(np.median(active_y))
    y0 = max(0, y_center - 14)
    y1 = min(h, y_center + 14)
    bw_band = bw[y0:y1, :]

    col_sum = bw_band.sum(axis=0)
    runs: list[tuple[int, int]] = []
    in_run = False
    sx = 0
    for x in range(w):
        if col_sum[x] > 0 and not in_run:
            in_run = True
            sx = x
        elif col_sum[x] == 0 and in_run:
            in_run = False
            runs.append((sx, x))
    if in_run:
        runs.append((sx, w))

    clean_boxes: list[tuple[int, int, int, int]] = []
    for sx, ex in runs:
        sub = bw_band[:, sx:ex]
        ay = np.where(sub.sum(axis=1) > 0)[0]
        if len(ay) == 0:
            continue
        cy0, cy1 = y0 + int(ay[0]), y0 + int(ay[-1]) + 1
        ink = int(bw[cy0:cy1, sx:ex].sum())
        cw = ex - sx
        ch = cy1 - cy0
        if ink < 5 or (ch <= 3 and cw <= 2 and ink < 6):
            continue
        if cw >= 21:
            mid_l = sx + max(6, cw // 3)
            mid_r = sx + min(cw - 6, (2 * cw) // 3 + 2)
            split_x = mid_l + int(np.argmin(col_sum[mid_l:mid_r]))
            for p_sx, p_ex in [(sx, split_x), (split_x, ex)]:
                psub = bw[y0:y1, p_sx:p_ex]
                pay = np.where(psub.sum(axis=1) > 0)[0]
                if len(pay) > 0:
                    clean_boxes.append((p_sx, y0 + int(pay[0]), p_ex, y0 + int(pay[-1]) + 1))
        else:
            clean_boxes.append((sx, cy0, ex, cy1))

    if len(clean_boxes) > 1:
        tall_boxes = [b for b in clean_boxes if (b[3] - b[1]) >= 12]
        if tall_boxes:
            min_tx = min(b[0] for b in tall_boxes)
            max_tx = max(b[2] for b in tall_boxes)
            clean_boxes = [
                b
                for b in clean_boxes
                if (b[3] - b[1]) >= 12
                or (min_tx - 4 <= b[0] and b[2] <= max_tx + 4 and b[1] > y_center)
            ]

    return clean_boxes


def _resize_patch_12x16(sub: np.ndarray) -> np.ndarray:
    """Deterministic bilinear resize of a 2D character patch to (16, 12) unit vector."""
    sh, sw = sub.shape
    th, tw = 16, 12
    ys = np.linspace(0, max(0, sh - 1), th)
    xs = np.linspace(0, max(0, sw - 1), tw)
    y0 = np.floor(ys).astype(int)
    y1 = np.minimum(y0 + 1, max(0, sh - 1))
    wy = (ys - y0)[:, None]
    x0 = np.floor(xs).astype(int)
    x1 = np.minimum(x0 + 1, max(0, sw - 1))
    wx = (xs - x0)[None, :]

    top = sub[y0[:, None], x0[None, :]] * (1 - wx) + sub[y0[:, None], x1[None, :]] * wx
    bot = sub[y1[:, None], x0[None, :]] * (1 - wx) + sub[y1[:, None], x1[None, :]] * wx
    out = top * (1 - wy) + bot * wy
    vec = out.flatten().astype(np.float32)
    norm = float(np.linalg.norm(vec))
    if norm > 1e-6:
        vec /= norm
    return vec


def _recognize_cell(cell_gray: np.ndarray, is_bold_col: bool) -> str:
    boxes = _segment_cell_chars(cell_gray)
    if not boxes:
        return ""
    thresh = min(190, int(np.percentile(cell_gray, 15) + 50))
    bw = (cell_gray < thresh).astype(np.float32)
    chars: list[str] = []
    for sx, sy, ex, ey in boxes:
        ch = ey - sy
        cw = ex - sx
        if ch <= 9 and cw <= 9:
            chars.append(".")
            continue
        vec = _resize_patch_12x16(bw[sy:ey, sx:ex])
        best_label = "0"
        best_sim = -1.0
        for style_is_bold, proto_map in ((True, _PROTO_BOLD_NP), (False, _PROTO_REGULAR_NP)):
            bonus = 0.03 if style_is_bold == is_bold_col else 0.0
            for label, p_vec in proto_map.items():
                sim = float(np.dot(vec, p_vec)) + bonus
                if sim > best_sim:
                    best_sim = sim
                    best_label = label
        chars.append(best_label)
    return "".join(chars)


def extract_scanned_table(
    pdf_bytes: bytes,
    filename: str | None = None,
    parser_used: Literal["fast", "ai"] = "fast",
) -> TableData:
    """
    Extract bordered tables from scanned PDF documents (such as ГБУ «Мосгоргеотрест»
    geodesic coordinate catalogs КГС) using deskew, grid-line detection, and prototype OCR.
    """
    pdf = pdfium.PdfDocument(pdf_bytes)
    page_count = len(pdf)
    all_rows: list[list[str]] = []
    detected_cols = 0
    has_kgs_header = False

    for page_idx in range(page_count):
        page = pdf[page_idx]
        pil_img = page.render(scale=200.0 / 72.0).to_pil()
        h_lines, deskewed = _deskew_and_find_h_lines(pil_img)
        if len(h_lines) < 2:
            continue
        v_lines, gray = _find_true_v_lines(deskewed, h_lines)
        if len(v_lines) < 2:
            continue

        num_cols = len(v_lines) - 1
        detected_cols = max(detected_cols, num_cols)

        start_row = 0
        if len(h_lines) >= 3 and num_cols >= 3:
            y1 = h_lines[1]
            left_Span_density = float(
                (gray[max(0, y1 - 3) : y1 + 4, v_lines[0] + 10 : v_lines[min(2, num_cols)] - 10] < 180).mean()
            )
            if left_Span_density < 0.08:
                start_row = 2
                has_kgs_header = True

        for r in range(start_row, len(h_lines) - 1):
            yt = h_lines[r] + 4
            yb = h_lines[r + 1] - 4
            if yb <= yt + 6:
                continue
            row_vals: list[str] = []
            for c in range(num_cols):
                xl = v_lines[c] + 8
                xr = v_lines[c + 1] - 8
                if xr <= xl + 6:
                    row_vals.append("")
                    continue
                val = _recognize_cell(gray[yt:yb, xl:xr], is_bold_col=(c < 2))
                row_vals.append(val)
            if any(v != "" for v in row_vals):
                all_rows.append(row_vals)

    pdf.close()

    if not all_rows:
        return TableData(
            headers=["Column 1"],
            rows=[],
            page_count=max(1, page_count),
            parser_used=parser_used,
            source_filename=filename,
        )

    if detected_cols == 5 and has_kgs_header:
        headers = ["№ точки п/п", "№ точки по съемке", "x, м", "y, м", "H, м"]
    else:
        headers = [f"Column {i + 1}" for i in range(detected_cols)]

    return TableData(
        headers=headers,
        rows=all_rows,
        page_count=max(1, page_count),
        parser_used=parser_used,
        source_filename=filename,
    )
